def polozhit(imya, stroki, polya):
    p = os.path.join(DROP, imya)
    with io.open(p, 'w', encoding='utf-8-sig', newline='') as f:
        w = csv.DictWriter(f, fieldnames=polya, delimiter=';')
        w.writeheader()
        for s in stroki:
            w.writerow(s)
    return p

